<?php $active_module='dashboard'; require_once __DIR__ . '/layout.php'; $u=$supplier_user; $pdo=db(); $properties=$pdo->prepare('SELECT COUNT(*) FROM properties WHERE supplier_id=?'); $properties->execute([$u['supplier_id']]); $propertyCount=(int)$properties->fetchColumn(); $insights=$pdo->prepare("SELECT priority,title,body FROM ai_insights WHERE supplier_id=? AND status='new' ORDER BY CASE priority WHEN 'high' THEN 1 WHEN 'medium' THEN 2 ELSE 3 END, id DESC LIMIT 3"); $insights->execute([$u['supplier_id']]); $icalHealth=$pdo->prepare("SELECT p.id, p.name, p.property_type, (SELECT COUNT(*) FROM ical_connections c WHERE c.property_id=p.id AND c.status='active') active_con, (SELECT COUNT(*) FROM ical_connections c WHERE c.property_id=p.id AND c.status<>'active') inactive_con, (SELECT MAX(c.last_sync_at) FROM ical_connections c WHERE c.property_id=p.id) last_sync_at, (SELECT COUNT(*) FROM ical_events e JOIN ical_connections c ON c.id=e.ical_connection_id WHERE c.property_id=p.id) block_count, (SELECT MAX(c.last_error) FROM ical_connections c WHERE c.property_id=p.id AND COALESCE(c.last_error,'')<>'') last_error FROM properties p WHERE p.supplier_id=? AND p.property_type IN ('villa','yacht') ORDER BY p.name"); $icalHealth->execute([$u['supplier_id']]); $icalHealthRows=$icalHealth->fetchAll(); supply_start('Günaydın, ' . explode(' ', $u['full_name'])[0], $active_module); ?>
<section class="stats"><article><span>AKTİF TESİS</span><b><?= $propertyCount ?></b><small>Satışa açık ürün</small></article><article><span>AKTİF ODA TİPİ</span><b>2</b><small>Yayınlanmaya hazır</small></article><article><span>BUGÜNÜN REZERVASYONU</span><b>—</b><small>Pilot verisi bekleniyor</small></article><article class="accent"><span>NEXUS AI</span><b>3</b><small>İşlem önerisi</small></article></section><section class="dashboard-grid"><article class="panel availability"><div class="panel-title"><div><span>CANLI OPERASYON</span><h2>Satışa hazır envanter</h2></div><a href="/nexustraveltech/tedarikci/tesisler">Tesisleri yönet →</a></div><div class="availability-row"><div><b>NEXUS Pilot Hotel</b><span>Fethiye · Otel</span></div><strong>Aktif</strong></div><div class="availability-row"><div><b>Deluxe Sea View</b><span>18 ünite · 2 yetişkin</span></div><strong>Hazır</strong></div><div class="availability-row"><div><b>Family Suite</b><span>8 ünite · 4 yetişkin</span></div><strong>Hazır</strong></div></article><article class="panel ai-panel"><div class="panel-title"><div><span>NEXUS AI / ÖNCELİKLER</span><h2>Bugün neye bakmalı?</h2></div><a href="/nexustraveltech/tedarikci/yapay-zeka">Tüm öneriler →</a></div><?php foreach($insights as $insight): ?><div class="insight <?= htmlspecialchars($insight['priority']) ?>"><b><?= htmlspecialchars($insight['title']) ?></b><p><?= htmlspecialchars($insight['body']) ?></p></div><?php endforeach; ?></article></section><?php if ($icalHealthRows): ?><section class="panel" style="margin-top:18px"><div class="panel-title"><div><span>iCAL SAĞLIK DURUMU</span><h2>Takvim senkronizasyonu</h2></div><a href="/nexustraveltech/tedarikci/ical-takvimler">iCal takvimler →</a></div><?php foreach ($icalHealthRows as $ic): $icStale = (int)$ic['active_con'] > 0 && ($ic['last_sync_at'] === null || strtotime((string)$ic['last_sync_at']) < time() - 7 * 86400); ?><div class="availability-row"><div><b><?= htmlspecialchars($ic['name']) ?></b><span><?= $ic['property_type'] === 'yacht' ? 'Yat' : 'Villa' ?> · <?= (int)$ic['active_con'] ?> aktif / <?= (int)$ic['inactive_con'] ?> pasif bağlantı · <?= (int)$ic['block_count'] ?> blok · son senkron <?= $ic['last_sync_at'] ? htmlspecialchars($ic['last_sync_at']) : 'henüz yok' ?><?= $ic['last_error'] ? ' · hata: ' . htmlspecialchars($ic['last_error']) : '' ?></span></div><?= (int)$ic['active_con'] > 0 ? ($icStale ? '<strong style="color:#8a6100">⚠ Eski senkron</strong>' : '<strong>Aktif</strong>') : '<strong style="color:#b0301a">Pasif</strong>' ?></div><?php endforeach; ?></section><?php endif; ?><?php supply_end(); ?>
